# -*- coding: utf-8 -*-
# Сверка с ответами учебника Мерзляк 10 (углублённый), часть 1: ключ расходился с ответом учебника; каждый случай пересчитан
# вручную, условие сверено со сканом учебника (OCR mistral_20d9886d2e80c0be).
KB = "ключ неверен (сверка с ответом учебника Мерзляк 10 и пересчёт вручную): "
SRC = "сверка с ответами учебника Мерзляк 10 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]

K("G10_TB_§28_28_10", r"$-\dfrac{2\pi}{3}$", "x = 2π/3 + 2πk; на [−2π; 3π/2] корни 2π/3 и −4π/3, сумма −2π/3 (было 2π/3 — пропущен корень −4π/3)")
K("G10_TB_§35_35_9_1", r"$5$", "f = x^{5/4}, f′ = (5/4)x^{1/4}, f′(256) = 5/4·4 = 5 (было 5/4)", dadd=OLD(r"$\dfrac{5}{4}$", "забыт множитель 256^{1/4} = 4"))
K("G10_TB_§22_22_3_4", r"$-\sin\left(\dfrac{\pi}{18}\right)$", "cos(5π/9) = cos(π/2 + π/18) = −sin(π/18) (было −cos(π/18))", dadd=OLD(r"$-\cos\left(\dfrac{\pi}{18}\right)$", "функция не заменена на кофункцию"))
