K("G10_TB_§37_37_18", r"Не является", "12x² = 12 ⇒ x = ±1, но f(1) = 4 ≠ 2 и f(−1) = −4 ≠ −22 — прямая не касательная (было x = −1)")
K("G10_TB_§10_10_25_4", r"$\dfrac{a^{2} + ab + b^{2}}{a^{\frac{4}{3}}}$", "(a³ − b³)/(a^{4/3}(a − b)) = (a² + ab + b²)/a^{4/3}; показатель 4/3 был вынесен на всю дробь (в ответах учебника a² + ab + b² — опечатка учебника, пересчитано)")
K("G10_TB_§39_39_24_3", r"$-22$", "вершина x = 3 вне [4; 5], функция возрастает, наименьшее y(4) = −22 (было −25 = y(3))", dadd=OLD(r"$-25$", "взято значение в вершине вне отрезка"))
K("G10_TB_§30_30_6_10", r"$x = \dfrac{\pi}{3} + \pi k$; $x = -\dfrac{\pi}{3} + \pi k$", "4s² − 15s + 9 = 0 для s = sin²x: s = 3/4 (s = 3 невозможно), x = ±π/3 + πk; корни ±π/4 + πk посторонние (было с ними)",
  dadd=OLD(r"$x = \dfrac{\pi}{4} + \pi k; x = -\dfrac{\pi}{4} + \pi k; x = \dfrac{\pi}{3} + \pi k; x = -\dfrac{\pi}{3} + \pi k$", "включены посторонние корни"))
K("G10_TB_§39_39_23_3", r"возрастает на $(\dfrac{7}{3}; +\infty)$, убывает на $(1; \dfrac{7}{3})$, $x = \dfrac{7}{3}$ — точка минимума", "f′ = (3x − 7)/(2(x − 1)^{3/2}), критическая точка 7/3 (было 5/3)")
