K("G10_TB_§37_37_1_5", r"$y = -1$", "f(π) = −1, f′(π) = −sin π = 0 ⇒ y = −1 (было −x + π)", dadd=OLD(r"$y = -x + \pi$", "f′(π) взято равным −1"))
